<script src="https://cdn.jsdelivr.net/npm/jquery@3.6.4/dist/jquery.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@4.6.2/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/admin-lte@3.2/dist/js/adminlte.min.js"></script><script src="https://cdn.jsdelivr.net/npm/flatpickr"></script><script src="https://cdn.jsdelivr.net/npm/flatpickr/dist/l10n/th.js"></script><script>
const fields=['PositionName','Headcount','Gender','AgeRange','Education','Wage','WorkSchedule','MilitaryStatus','Conditions','ExpireDate','Remark'];let positionRowIndex=0;
const thaiMonthNames=["มกราคม","กุมภาพันธ์","มีนาคม","เมษายน","พฤษภาคม","มิถุนายน","กรกฎาคม","สิงหาคม","กันยายน","ตุลาคม","พฤศจิกายน","ธันวาคม"];
function toThaiBuddhistText(date){return date?`${date.getDate()} ${thaiMonthNames[date.getMonth()]} ${date.getFullYear()+543}`:''}
function initThaiDatePicker(el){flatpickr(el,{locale:'th',dateFormat:'Y-m-d',altInput:true,altInputClass:'form-control form-control-sm',allowInput:false,onReady:(d,s,i)=>{i.altInput.value=toThaiBuddhistText(d[0])},onChange:(d,s,i)=>{i.altInput.value=toThaiBuddhistText(d[0])},onValueUpdate:(d,s,i)=>{i.altInput.value=toThaiBuddhistText(d[0])}})}
function addRow(){const rowIndex=positionRowIndex++;const tr=document.createElement('tr');tr.className='position-row';tr.innerHTML=fields.map((f,i)=>`<td><${f==='Conditions'||f==='Remark'?'textarea':'input'} ${f==='Headcount'?'type="number" min="1" value="1"':f==='ExpireDate'?'type="text" readonly':'type="text"'} class="form-control form-control-sm${f==='ExpireDate'?' expire-date-picker':''}" name="positions[${rowIndex}][${f}]" ${i===0?'required':''}></${f==='Conditions'||f==='Remark'?'textarea':'input'}></td>`).join('')+'<td class="actions"><button type="button" class="btn btn-outline-danger btn-sm remove-row" title="ลบตำแหน่ง"><i class="fas fa-trash"></i></button></td>';document.querySelector('#positionRows').appendChild(tr);initThaiDatePicker(tr.querySelector('.expire-date-picker'))}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
const employerFillFields=['EmployerName','BusinessType','EmployeeCount','EmployerPhone','IssuedBy','BuildingName','HouseNo','Moo','Soi','Road','Subdistrict','District','Province','PostalCode','ContactName','ContactPosition'];
function lookupEmployer(){const id=document.querySelector('#employerIdInput').value.trim();const msg=document.querySelector('#employerLookupMsg');if(!id){msg.innerHTML='';msg.className='small-help mt-1';return}msg.innerHTML='<i class="fas fa-spinner fa-spin"></i> กำลังค้นหา...';msg.className='small-help mt-1 searching';fetch('api/vacancy_employer_lookup.php?EmployerID='+encodeURIComponent(id)).then(r=>r.json()).then(res=>{if(res.success){fillEmployerFields(res.data)}else{msg.innerHTML='<i class="fas fa-info-circle"></i> ไม่พบข้อมูลนายจ้างรายนี้ กรอกข้อมูลใหม่ได้เลย';msg.className='small-help mt-1 notfound'}}).catch(()=>{msg.innerHTML='';msg.className='small-help mt-1'})}
document.querySelector('#employerIdInput').addEventListener('blur',lookupEmployer);
let employerSearchTimeout,employerSuggestionItems=[];
function fillEmployerFields(data){employerFillFields.forEach(f=>{const el=document.querySelector(`[name="${f}"]`);if(el)el.value=data[f]??''});const msg=document.querySelector('#employerLookupMsg');msg.innerHTML='<i class="fas fa-check-circle"></i> พบข้อมูลนายจ้างเดิม ดึงข้อมูลอัตโนมัติแล้ว';msg.className='small-help mt-1 found'}
document.querySelector('#employerIdInput').addEventListener('input',function(){clearTimeout(employerSearchTimeout);const q=this.value.trim();const box=document.querySelector('#employerSuggestions');if(!q){box.style.display='none';box.innerHTML='';employerSuggestionItems=[];return}employerSearchTimeout=setTimeout(()=>{fetch('api/vacancy_employer_search.php?q='+encodeURIComponent(q)).then(r=>r.json()).then(res=>{employerSuggestionItems=res.data||[];if(!employerSuggestionItems.length){box.innerHTML='<div style="padding:10px 12px;color:#999">ไม่พบข้อมูลนายจ้าง</div>';box.style.display='block';return}box.innerHTML=employerSuggestionItems.map((it,i)=>`<div class="employer-suggestion" data-idx="${i}" style="padding:10px 12px;cursor:pointer;border-bottom:1px solid #eee"><strong style="color:#002D62">${esc(it.EmployerID||'(ไม่มีเลขประจำตัว)')}</strong><br><small style="color:#999">${esc(it.EmployerName)}</small></div>`).join('');box.style.display='block'}).catch(()=>{box.style.display='none'})},300)});
document.querySelector('#employerSuggestions').addEventListener('mousedown',function(e){const item=e.target.closest('.employer-suggestion');if(!item)return;e.preventDefault();const data=employerSuggestionItems[Number(item.dataset.idx)];if(!data)return;document.querySelector('#employerIdInput').value=data.EmployerID||'';fillEmployerFields(data);this.style.display='none'});
document.addEventListener('click',function(e){if(!e.target.closest('#employerIdInput,#employerSuggestions'))document.querySelector('#employerSuggestions').style.display='none'});
function validatePanel(panel){const invalid=[...panel.querySelectorAll('[required]')].find(x=>!String(x.value||'').trim());if(invalid){invalid.reportValidity();invalid.focus();return false}return true}
const form=document.querySelector('#vacancyForm'),stepPanels=[document.querySelector('#employerSection'),document.querySelector('#positionsSection')],review=document.querySelector('#reviewSection');let currentStep=0;
const stepper=document.createElement('div');stepper.className='form-stepper';stepper.innerHTML='<div class="form-step"><span class="step-number">1</span><span>ข้อมูลนายจ้าง</span></div><div class="form-step-line"></div><div class="form-step"><span class="step-number">2</span><span>ตำแหน่งงานว่าง</span></div><div class="form-step-line"></div><div class="form-step"><span class="step-number">3</span><span>ตรวจสอบข้อมูล</span></div>';form.before(stepper);
const employerNext=document.createElement('div');employerNext.className='card-footer';employerNext.innerHTML='<div class="step-actions"><span class="small-help">กรอกข้อมูลที่มีเครื่องหมาย * ให้ครบถ้วน</span><button type="button" class="btn btn-primary" id="toPositions">ถัดไป <i class="fas fa-arrow-right ml-1"></i></button></div>';document.querySelector('#employerSection').appendChild(employerNext);
function refreshReview(){const value=n=>String(document.querySelector(`[name="${n}"]`)?.value||'').trim()||'-';document.querySelector('#reviewEmployer').textContent=value('EmployerName');document.querySelector('#reviewContact').textContent=value('ContactName');document.querySelector('#reviewPhone').textContent=value('EmployerPhone');const rows=[...document.querySelectorAll('.position-row')];document.querySelector('#reviewCount').textContent=`${rows.length} ตำแหน่ง`;document.querySelector('#reviewPositions').innerHTML=rows.map(row=>{const n=row.querySelector('[name*="[PositionName]"]')?.value.trim()||'-';const c=row.querySelector('[name*="[Headcount]"]')?.value||'1';return `<li><strong>${esc(n)}</strong> จำนวน ${esc(c)} อัตรา</li>`}).join('')}
function showStep(step){currentStep=step;stepPanels.forEach((p,i)=>p.classList.toggle('active',i===step));review.classList.toggle('active',step===2);document.querySelectorAll('.form-step').forEach((s,i)=>{s.classList.toggle('active',i===step);s.classList.toggle('completed',i<step)});if(step===2)refreshReview();window.scrollTo({top:stepper.offsetTop-16,behavior:'smooth'})}
document.querySelector('#toPositions').onclick=()=>{if(validatePanel(stepPanels[0]))showStep(1)};document.querySelector('#toReview').onclick=()=>{if(validatePanel(stepPanels[1]))showStep(2)};document.querySelector('#backToEmployer').onclick=()=>showStep(0);document.querySelector('#backToPositions').onclick=()=>showStep(1);
form.addEventListener('reset',()=>setTimeout(()=>showStep(0),0));document.querySelector('#addRow').onclick=addRow;document.querySelector('#positionRows').addEventListener('click',e=>{if(e.target.closest('.remove-row')&&document.querySelectorAll('.position-row').length>1)e.target.closest('tr').remove()});addRow();
function loadNotices(){fetch('api/vacancy_notice_list.php').then(r=>r.json()).then(x=>{document.querySelector('#noticeTable tbody').innerHTML=(x.data||[]).map((n,i)=>`<tr><td>${i+1}</td><td>${esc(n.EmployerName)}</td><td>${esc(n.PositionName)}</td><td>${n.Headcount||0}</td><td>${esc(n.Wage||'-')}</td><td>${esc(n.Gender||'-')}</td><td>${esc(n.AgeRange||'-')}</td><td>${esc(n.Education||'-')}</td><td>${esc(n.Conditions||'-')}</td><td>${esc(n.WorkSchedule||'-')}</td><td>${esc(n.Remark||'-')}</td><td><button class="btn btn-outline-danger btn-sm delete-notice" data-id="${esc(n.NoticeID)}"><i class="fas fa-trash"></i></button></td></tr>`).join('')}).catch(()=>{})}loadNotices();document.querySelector('#noticeTable').addEventListener('click',e=>{const b=e.target.closest('.delete-notice');if(b&&confirm('ยืนยันการลบใบแจ้งนี้หรือไม่')){const d=new FormData();d.append('NoticeID',b.dataset.id);fetch('api/vacancy_notice_delete.php',{method:'POST',body:d}).then(()=>loadNotices())}});
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{const data=new FormData(form);const masterRes=await fetch('api/vacancy_employer_save.php',{method:'POST',body:data});const master=await masterRes.json();if(!master.success)throw new Error(master.message||'บันทึกข้อมูลนายจ้างไม่สำเร็จ');data.append('EmployerNo',master.EmployerNo);const noticeRes=await fetch('api/vacancy_notice_save.php',{method:'POST',body:data});const result=await noticeRes.json();if(!result.success)throw new Error(result.message||'บันทึกใบแจ้งไม่สำเร็จ');alert('บันทึกข้อมูลเรียบร้อย');form.reset();document.querySelector('#positionRows').innerHTML='';positionRowIndex=0;addRow();loadNotices()}catch(err){alert(err.message||'ไม่สามารถบันทึกข้อมูลได้')}finally{button.disabled=false}});showStep(0);
</script></body></html>